internal final class NVHumanResoureNumSeq extends NumberSeqApplicationModule
{
}

Method.Source:
protected void loadModule()
{
    NumberSeqDatatype datatype = NumberSeqDatatype::construct();

    datatype.parmDatatypeId(extendedTypeNum(NVOvertimeId));
    datatype.parmReferenceHelp(literalStr("Overtime Id"));
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardFetchAheadQty(10);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmSortField(1);

    datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(datatype);

    datatype.parmDatatypeId(extendedtypenum(NVHcmJobNumSequence));
    datatype.parmReferenceHelp(literalstr("Job Id NS"));
    datatype.parmReferenceLabel(literalstr("Job Id NS"));
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmWizardHighest(99999999);
    datatype.parmWizardfetchAheadQty(10);
    datatype.parmSortField(23);

    this.create(datatype);
}
